import{_ as e,c as p,o as r,af as h}from"./chunks/framework.BKeRpnBD.js";const b=JSON.parse('{"title":"漸","description":"高岛易断 - 漸","frontmatter":{"title":"漸","description":"高岛易断 - 漸"},"headers":[],"relativePath":"zh/classics/takashima/053.md","filePath":"zh/classics/takashima/053.md"}'),i={name:"zh/classics/takashima/053.md"};function l(n,a,d,t,s,c){return r(),p("div",null,[...a[0]||(a[0]=[h('<h1 id="漸" tabindex="-1">漸 <a class="header-anchor" href="#漸" aria-label="Permalink to “漸”">​</a></h1><h2 id="漸-1" tabindex="-1">漸 <a class="header-anchor" href="#漸-1" aria-label="Permalink to “漸”">​</a></h2><h2 id="卦辞" tabindex="-1">卦辞 <a class="header-anchor" href="#卦辞" aria-label="Permalink to “卦辞”">​</a></h2><p>渐：女归吉，利贞。</p><h2 id="卦辞注" tabindex="-1">卦辞注 <a class="header-anchor" href="#卦辞注" aria-label="Permalink to “卦辞注”">​</a></h2><p>《渐》反为《归妹》，其象同取于女，《归妹》之少女，以悦而归，不如《渐》之长女，以顺而归也。以顺而归，则媒妁言之，父母命之，及长而字，则渐而来，得其正也，故曰“女归吉”。《艮》男《兑》女，其卦曰《咸》，以男娶女也，故先戒以“利贞”，而后曰“娶女吉”；《渐》以《艮》男《巽》女，以女归男也，故先曰“女归吉”，而后告以“利贞”。</p><h2 id="象辞" tabindex="-1">象辞 <a class="header-anchor" href="#象辞" aria-label="Permalink to “象辞”">​</a></h2><p>山上有木，渐。君子以居贤德善俗。</p><h2 id="象辞注" tabindex="-1">象辞注 <a class="header-anchor" href="#象辞注" aria-label="Permalink to “象辞注”">​</a></h2><p>山上有木，以木在山，为得其所，犹女子以归为得所。君子法此象，观木之由渐而长，非一时所可成，即知俗之由渐而善，非一旦所能化。要必先居德以为表率，使之渐仁摩义，而风俗自善。古称缺妻之贤，孟光之德，足以化俗，况士君子之躬居贤德者乎？其化民成俗，固有日进而日善者也。全卦皆取《巽》女，而《象》独称“君子”，盖《艮》为贤人，故曰“君子居贤德”。要知君子与淑女，足为配偶，其德同，其化亦同也。“善俗”，王肃本作风俗，“居贤德”，《本义》云“贤字衍”。</p><h2 id="占断" tabindex="-1">占断 <a class="header-anchor" href="#占断" aria-label="Permalink to “占断”">​</a></h2><p>○　问时运：如木在高山，得逢春生发之象。</p><p>○　问营商：山藏货财，木能生发，且《巽》为商，利市三倍，得此卦象，自必能逐渐得利也。</p><p>○　问功名：足膺贤才之选。</p><p>○　问战征：防三军前进，在深山茂林之处，有敌兵埋伏。</p><p>○　问婚姻：必是贤德淑女，是以“君子好逑”。</p><p>○　问家宅：必是德门仁里，君子居之。</p><p>○　问疾病：是木克土之症，宜安居调养。</p><p>○　问六甲：望前生者男，望后生者女。</p><h2 id="初六解" tabindex="-1">初六解 <a class="header-anchor" href="#初六解" aria-label="Permalink to “初六解”">​</a></h2><p>鸿，水禽，来往有时，群飞有序。相传汉土婚礼用雁，取其飞行不乱，失偶不再，有女贞之象。大曰鸿，小曰雁，鸿与雁一也。《彖》曰“女归”，故六爻皆取喻于鸿。“干”，水湄，鸿渐干而得所栖，犹女适人而得所托。但《艮》为少男，故称“小子”，《巽》为长女，一长一少，年齿相悬，未免于归愆期，或有不测之变，是为“小于厉”也。《说卦》“成言乎艮”，有言，为有成言也。女子许嫁，惟凭媒妁之言，既有其言，不得以有变而渝，故曰“有言无咎”。初应在上，初与上爻，高下悬殊，即可见夫妇年齿，长幼亦悬殊。女能待年不乱，守礼无失，无所为厉，复有何咎？《彖传》以“义无咎”释之，盖谓义在则然，咎自无焉。</p><h2 id="初六占" tabindex="-1">初六占 <a class="header-anchor" href="#初六占" aria-label="Permalink to “初六占”">​</a></h2><p>○　问时运：人微年少，运途初行，虽危无咎。</p><p>○　问战征：屯军江干，防有危厉，幸有谍言来告，得以免咎。</p><p>○　问营商：货物交易，防有小人从中作难，因约言早成，得以无害。</p><p>○　问功名：鸿运亨通，初虽在下，自有渐进之象。</p><p>○　问婚姻：女长男少，妁言既定，当以待年而嫁，无咎也。</p><p>○　问家宅：此宅临水，防小人有疾厄，然无大咎。</p><p>○　问疾病：不利小人，大人无咎。</p><p>○　问六甲：生女。</p><h2 id="初六案例" tabindex="-1">初六案例 <a class="header-anchor" href="#初六案例" aria-label="Permalink to “初六案例”">​</a></h2><p>友人某来请占事业成否，筮得《渐》之《家人》。</p><p>断曰：《渐》者，渐而进也，《渐》在初爻，为进步之初基也。“干”，水涯，亦低下之处。君占事业，得《渐》初爻，知君此业，必是初次开办，如秋雁初来，尚在江干飞集，未得远翔。凡事业初创，未免有小人出而阻扰，务要把定初志，不改成言，是得无咎。然在初爻，其进犹微，必得四年后，行到上爻，则得其应援，必可大获利益也。</p><h2 id="六二解" tabindex="-1">六二解 <a class="header-anchor" href="#六二解" aria-label="Permalink to “六二解”">​</a></h2><p>磐者，水中平石，“衎衎”，和乐之貌。“鸿渐于磐”，有水可饮，有蒲鱼稻梁可食，为足乐也，犹女子嫁得其夫，合卺而饮，共牢而食，自见“宜室宜家，和乐且耽”。二与五相应，即为配偶，妇人贤德，足以内助，固非虚食夫家之食者也。《彖传》以“不素饱”释之，即此意也。</p><h2 id="六二占" tabindex="-1">六二占 <a class="header-anchor" href="#六二占" aria-label="Permalink to “六二占”">​</a></h2><p>○　问时运：既得安乐，又得醉饱无忧，吉。</p><p>○　问战征：兵食充足，军心欢悦，自有安似磐石之象。</p><p>○　问营商：二爻居《巽》之中，《巽》为商，为利。就爻辞言“干”进“磐”，有渐进渐高之势，吉。</p><p>○　问功名：有嘉宾宴乐之象，成名必矣，吉。</p><p>○　问婚姻：二与五相应，即以二五为婚；二五皆吉，可咏百年偕老矣。</p><p>○　问家宅：此宅地基巩固，一门和乐，吉。</p><p>○　问疾病：饮食过度所致，宜消食安胃，病即日可愈。</p><p>○　问六甲：生女。</p><h2 id="六二案例" tabindex="-1">六二案例 <a class="header-anchor" href="#六二案例" aria-label="Permalink to “六二案例”">​</a></h2><p>明治二十三年，占某贵显气运，筮得《渐》之《巽》。</p><p>断曰：二爻居《巽》之中，《巽》，顺也。爻辞曰“鸿渐于磐”，鸿，大雁也，磐，山石之安者。贵下占气运得此爻，知贵下鸿运通顺，持躬涉世，皆得安如磐石，无人得而动摇。由“干”进“磐”，见鸿飞踪迹，逐步增高，喻贵下卒业东北学校，继复游学欧美各邦，学识亦渐步长进。且二爻与五相应，爻以夫妇和谐，即可见君巨之喜乐，至美衣饱食，和乐衎衎，本贵下所素有也，吉何如也！</p><p>明治三十二年，占北海道厅气运，筮得《渐》之《巽》。</p><p>断曰：《渐》者渐进也，由乱而进于治，由衰而进于盛，皆有渐进之象焉。今占北海道厅气运，而得《渐》之二爻，爻辞曰“鸿渐于磐”，由“干”而进于“磐”，是亦渐进而渐高也，知北海道厅治象，当必日进日盛。爻又曰“饮食衎衎”，在北海一带，为鱼临蜃蛤之乡，其足供饮食者，出产饶富，民居斯土，获斯利，家室丰盈，雍雍和乐，自得“饮食衎衎”之喜。爻辞曰“吉”，信可知也。</p><h2 id="九三解" tabindex="-1">九三解 <a class="header-anchor" href="#九三解" aria-label="Permalink to “九三解”">​</a></h2><p>“陆”，高平之地，鸿所集也。九三阳刚为夫，六四阴柔为妇，三又与六正应，六亦曰“陆”。自内往外为征，三往就外之陆，而遂弃内之陆，故“不复”。上互《离》，《离》为大腹，孕之象；下互《坎》，《坎》为灾，为鬼，不育之象。三与四以比邻私通，坏彝伦之大纲，背渐进之大义，安能得室家和睦，夫妇偕老，生育以延嗣续之庥乎？故曰“夫征不复，妇孕不育，凶”。且雁呼芦避缴，巡呼警夜，飞则相随，止则相保，亦有御寇之象，故曰“利御寇”。夫鸿之有雌雄，犹人之有夫妇也，雄飞不返，是离其群矣；胎孕之道，期其长育，孕而不育，是失其道矣。雌雄相守，是所以“御寇”，是“顺相保”也。《彖传》逐句释之，有以夫！</p><h2 id="九三占" tabindex="-1">九三占 <a class="header-anchor" href="#九三占" aria-label="Permalink to “九三占”">​</a></h2><p>○　问时运：运途不正，防有外祸。</p><p>○　问战征：利于守御，不利往征。</p><p>○　问营商：难望获利，防有盗劫之虞。</p><p>○　问功名：惟从事军政，可以得名。</p><p>○　问婚姻：防有始乱终离之憾。</p><p>○　问家宅：此宅于生产不利。</p><p>○　问疾病：妇人生产，恐母子不能两全。</p><p>○　问六甲：生女。</p><h2 id="九三案例" tabindex="-1">九三案例 <a class="header-anchor" href="#九三案例" aria-label="Permalink to “九三案例”">​</a></h2><p>昔余在囚之日，有狱吏和田某者，突然谓余曰：今兹罪案，曷不卜之？先是余自占气运，得《艮》之《渐》，断辞详记需三爻；今复一占，筮得《渐》之《观》。</p><p>断曰：“夫征不复”，谓此案已往，不复追究矣。“妇孕”者，谓祸胎也，“不育”者，谓此案不致再生枝节矣。“御寇”者，谓审狱之官也；“顺相保”者，谓必能保护我身也。然所谓相保者，当必在和田氏矣。后一二旬，前奉行退职，清水某袭其后，和田氏为奉行次席，于是二氏相谋，以五十月徒期，减为二十月，余乃得以出罪。</p><h2 id="六四解" tabindex="-1">六四解 <a class="header-anchor" href="#六四解" aria-label="Permalink to “六四解”">​</a></h2><p>四居《巽》之始，《巽》为木。鸿水鸟，本不栖木，“桷”者，枝柯之大而平者也，于木之中，而得方平之桷，则亦可以容足矣。“或”者幸得之辞，此以鸿之失所，喻妇之失所也。四夫在三，三“征不复”，四妇失其所矣，或得其桷而集之，亦无咎焉。巽顺自守，不失妇道之正，虽无夫可也。</p><h2 id="六四占" tabindex="-1">六四占 <a class="header-anchor" href="#六四占" aria-label="Permalink to “六四占”">​</a></h2><p>○　问时运：运失其正，但以顺自处，随遇得安，亦可无咎。</p><p>○　问营商：聊有所得，差足免咎。</p><p>○　问战征：得其倚角，敌势已衰。</p><p>○　问功名：从事角逐，所得亦微。</p><p>○　问疾病：病在肝木太盛，宜顺气调养。</p><p>○　问家宅：此宅多寡居之妇，有遇人不淑之感。</p><p>○　问行人：在外失年，聊以将顺容身，一时不归。</p><p>○　问六甲：生男。</p><h2 id="六四案例" tabindex="-1">六四案例 <a class="header-anchor" href="#六四案例" aria-label="Permalink to “六四案例”">​</a></h2><p>旧大垣藩主华族户田氏，奉侍萱堂，借余神奈川别墅，闲居养病者数月，医士户冢文海氏间日自东京来诊。一日户冢氏谓余曰：诊视户田太君之疾，四五日前，颇为可虑，近少轻快，惟老衰难期速效。余曰：顷日代为问卜筮得《渐》之《遁》，今玩爻辞，知太君近病无妨，恐明后年命限有阻。</p><p>户冢氏俯首不语。有松野家老出而问曰：我太君之命，其终于明后年乎？余曰：请勿与外人道也！后三年，太君果仙逝，会葬之日，户冢氏追述前言，感叹《易》理之前知。盖《渐》为长女，卦为归魂，自四至上，三爻为三年，由是推之，死期可预决也。</p><h2 id="九五解" tabindex="-1">九五解 <a class="header-anchor" href="#九五解" aria-label="Permalink to “九五解”">​</a></h2><p>《尔雅》，“大阜曰陵”；又八陵，北陵、西俞、雁门是也。此陵当是北陵，雁之家也。《月令》，“季秋鸿雁来宾”，鸿之南来为宾，北陵则为家，孕育则在家也。五与二正应，为夫妇，故以“鸿渐于陵”，喻夫妇之居家也。三至五互《离》，《离》为大腹，三动则《离》坏，故“不孕”；自二至五历三爻，象“三岁”。《艮》少男，《巽》长女，女及笄，而男犹未冠，是以不能生育，迨及时而阴阳和合，自然得孕矣。男少女长，似女偏胜，然二五正应，内外得当，夫倡妇随，故曰“终莫之胜”。时至而孕，各得所愿，吉可知也。又云：此卦三五皆言妇，九五以二为妇，正也，九三以四为妇，非正也。故三四相比为夫妇，虽孕而不敢育。女之归不以渐也，故凶；二五以相应为夫妇，不孕而得所愿，女之归以渐也，故吉。</p><h2 id="九五占" tabindex="-1">九五占 <a class="header-anchor" href="#九五占" aria-label="Permalink to “九五占”">​</a></h2><p>○　问时运：运途中正，三年后，无往不利，吉。</p><p>○　问战征：屯军大阜，三年后，所向无敌，吉。</p><p>○　问功名：三年后必成。</p><p>○　问营商：目下难望获利，至上爻自可独占厚利，盖在三岁后也。</p><p>○　问婚姻：得子稍迟，吉。</p><p>○　问家宅：宅在大阜之间，吉。</p><p>○　问六甲：生男。</p><h2 id="九五案例" tabindex="-1">九五案例 <a class="header-anchor" href="#九五案例" aria-label="Permalink to “九五案例”">​</a></h2><p>某商人来请占气运，筮得《渐》之《艮》。</p><p>断曰：五居外卦之中，进步已高，得渐于大阜之上，无可再进也。足下占气运而得此爻，知足下营商多载，虽事业渐进渐高，而不得一时获利，如鸿鸟雌雄相随，而一大一小，未能即时生育也。鸿待三年后可孕，知商业亦必待三年后，可获大利也。“终莫之胜”者，谓非他人所能及也。爻辞曰“吉”，吉可知也。《象》曰“得所愿”，知足下平生之志愿，可遂矣。</p><h2 id="上九解" tabindex="-1">上九解 <a class="header-anchor" href="#上九解" aria-label="Permalink to “上九解”">​</a></h2><p>上与三皆处卦极，故并称“陆”。《渐》卦六爻，皆取象于鸿，以喻夫妇，即本《彖》辞“女归”之旨。三之《渐》“陆”，夫道不正，致妇失所，不如鸿之雌雄相守；上则犹是陆也，犹是渐也，而以礼相接，人咸称美，不特表闺阃之令范，且足树邦国之合仪矣。一羽本轻，而先王制礼，纳采问名，皆取以为用，非以其有偶而不乱乎？夫妇之道，亦如是焉，故曰“其羽可用为仪”。“女归”之“吉”，其以此乎？</p><h2 id="上九占" tabindex="-1">上九占 <a class="header-anchor" href="#上九占" aria-label="Permalink to “上九占”">​</a></h2><p>○　问时运：气运正盛，可出而用也，吉。</p><p>○　问战征：从平陆进军，威仪显赫，攻无不克</p><p>○　问营商：货美价高，定可获利。</p><p>○　问功名：出而用世，可以仪表天下。</p><p>○　问婚姻：吉。</p><p>○　问家宅：此宅地位崇高，瞻观有耀，吉。</p><p>○　问六甲：生男。</p><h2 id="上九案例" tabindex="-1">上九案例 <a class="header-anchor" href="#上九案例" aria-label="Permalink to “上九案例”">​</a></h2><p>明治十九年，虎列喇病流行于横滨，凡横滨店中，家族皆避疫于神奈川别庄，东京之友，皆归东京，余携远来学者八人，赴箱根木贺。一日有东京门人，判事尾藤某来状，其旨曰：今度拜命，赴越后高田裁判所长，临发自筮，爻象不吉，请为再占气运如何？筮得《渐》之《蹇》。</p><p>断曰：全卦以渐进为义，爻至上六，渐进之义已终，进无可进，是暖回冰解，鸿鸟北还之时。今占尾藤氏气运，得此上爻，知为新授北国高田判事之任。爻辞所云“鸿渐于陆”，辞意适合，本是吉象，但此爻《易》三百八十四爻中，为归魂八爻之一，占者当此，生命有阻。因叹曰：氏为余门人中之翘楚，他日继余《易》学者，在此人也，大为可惜！一时从者闻此断词，皆谓共在一堂，何得以一筮之下，遽断必死？后尾藤赴任高田，未几果殁。</p>',103)])])}const m=e(i,[["render",l]]);export{b as __pageData,m as default};
